import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
public class Main { public static void main(String[] args) throws IOException { Path path = Path.of("read.txt"); Files.writeString(path, "Hello file"); System.out.println(Files.readString(path)); } }

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
public class Main { public static void main(String[] args) throws IOException { Path path = Path.of("lines.txt"); Files.writeString(path, "One\nTwo\nThree"); System.out.println(Files.readAllLines(path).size()); } }

import java.io.BufferedReader;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
public class Main { public static void main(String[] args) throws IOException { Path path = Path.of("items.txt"); Files.writeString(path, "Pen\nBook"); try (BufferedReader reader = Files.newBufferedReader(path)) { String line; while ((line = reader.readLine()) != null) System.out.println(line); } } }

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
public class Main { public static void main(String[] args) throws IOException { Path path = Path.of("utf8.txt"); Files.writeString(path, "Learning", StandardCharsets.UTF_8); System.out.println(Files.readString(path, StandardCharsets.UTF_8)); } }

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
public class Main { public static void main(String[] args) throws IOException { Path path = Path.of("count.txt"); Files.writeString(path, "Java"); String text = Files.readString(path); System.out.println(text.length()); } }
